@@ -0,0 +1,72 @@
+/**
+ * Sanitize SVG content to prevent XSS attacks.
+ * Removes dangerous elements and attributes from SVG strings.
+ */
+
+/**
+ * List of dangerous SVG/HTML elements that can execute scripts.
+ */
+const DANGEROUS_ELEMENTS = [
+    'script',
+    'animate',
+    'set',
+    'animateMotion',
+    'animateTransform',
+    'animateColor',
+    'handler',
+    'listener',
+    'prefetch',
+    'discard'
+];
+
+/**
+ * List of dangerous attributes that can execute scripts.
+ */
+const DANGEROUS_ATTRIBUTES = [
+    'onload',
+    'onunload',
+    'onclick',
+    'ondblclick',
+    'onmousedown',
+    'onmouseup',
+    'onmouseover',
+    'onmousemove',
+    'onmouseout',
+    'onfocus',
+    'onblur',
+    'onkeypress',
+    'onkeydown',
+    'onkeyup',
+    'onsubmit',
+    'onreset',
+    'onselect',
+    'onchange',
+    'onerror',
+    'onabort',
+    'onresize',
+    'onactivate',
+    'onbegin',
+    'onend',
+    'onrepeat'
+];
+
+/**
+ * Sanitize an SVG string by removing dangerous elements and attributes.
+ * @param {string} svgString - The SVG string to sanitize.
+ * @returns {string} - The sanitized SVG string.
+ */
+const sanitize = function (svgString) {
+    const parser = new DOMParser();
+    const doc = parser.parseFromString(svgString, 'image/svg+xml');
+
+    // Remove dangerous elements
+    for (const tagName of DANGEROUS_ELEMENTS) {
+        const elements = doc.getElementsByTagNameNS('*', tagName);
+        // Iterate in reverse since we're removing elements
+        for (let i = elements.length - 1; i >= 0; i--) {
+            elements[i].parentNode.removeChild(elements[i]);
+        }
+    }
+
+    // Remove dangerous attributes from all elements
+    const allElements = doc.getElementsByTagName('*');
+    for (let i = 0; i < allElements.length; i++) {
+        const element = allElements[i];
+        for (const attr of DANGEROUS_ATTRIBUTES) {
+            if (element.hasAttribute(attr)) {
+                element.removeAttribute(attr);
+            }
+        }
+        // Remove any attribute starting with 'on' (event handlers)
+        const attrsToRemove = [];
+        for (let j = 0; j < element.attributes.length; j++) {
+            const attrName = element.attributes[j].name.toLowerCase();
+            if (attrName.startsWith('on')) {
+                attrsToRemove.push(attrName);
+            }
+        }
+        for (const attr of attrsToRemove) {
+            element.removeAttribute(attr);
+        }
+        // Remove javascript: URLs from href and xlink:href attributes
+        for (const hrefAttr of ['href', 'xlink:href', 'src', 'action']) {
+            if (element.hasAttribute(hrefAttr)) {
+                const val = element.getAttribute(hrefAttr).trim().toLowerCase();
+                if (val.startsWith('javascript:') || val.startsWith('data:text/html')) {
+                    element.removeAttribute(hrefAttr);
+                }
+            }
+        }
+    }
+
+    // Serialize back to string
+    const serializer = new XMLSerializer();
+    return serializer.serializeToString(doc.documentElement);
+};
+
+module.exports = {sanitize};

