+'use strict';
+
+const path = require('path');
+
+/**
+ * Validates that a resolved file path does not escape the given base directory.
+ * Throws an error if path traversal is detected.
+ *
+ * @param {string} baseDir - The allowed base directory (absolute path)
+ * @param {string} filePath - The file path to validate (may be relative or absolute)
+ * @returns {string} The resolved, safe absolute path
+ */
+function validateLocalPath(baseDir, filePath) {
+  const resolvedBase = path.resolve(baseDir);
+  const resolvedFile = path.resolve(baseDir, filePath);
+
+  if (!resolvedFile.startsWith(resolvedBase + path.sep) && resolvedFile !== resolvedBase) {
+    throw new Error(`Path traversal detected: ${filePath} is outside of ${baseDir}`);
+  }
+
+  return resolvedFile;
+}
+
+module.exports = validateLocalPath;
