+ *
+ * @param {string} baseDir - The allowed base directory
+ * @param {string} filePath - The requested file path
+ * @param {function} callback - Node-style callback(err, data)
+ */
+function safeReadFile(baseDir, filePath, callback) {
+  let safePath;
+  try {
+    safePath = validateLocalPath(baseDir, filePath);
+  } catch (e) {
+    return callback(e);
+  }
+  fs.readFile(safePath, callback);
