+ * Synchronously reads a local file, preventing path traversal attacks.
+ *
+ * @param {string} baseDir - The allowed base directory
+ * @param {string} filePath - The requested file path
+ * @returns {Buffer} File contents
+ */
+function safeReadFileSync(baseDir, filePath) {
+  const safePath = validateLocalPath(baseDir, filePath);
+  return fs.readFileSync(safePath);
+}
+
+module.exports = { safeReadFile, safeReadFileSync };
